import { lstat, readdir, readFile, realpath, rmdir, unlink } from 'node:fs/promises'
import path from 'node:path'

/** Remove only the three files generated by the retired --patch loader. Archives are separate. */
export async function cleanupLegacyCompanion(storage: string): Promise<number> {
  const root = path.resolve(storage, 'editor-companion', 'runtime')
  let directories: string[]
  try {
    const canonical = path.join(await realpath(storage), 'editor-companion', 'runtime')
    const normalize = (value: string): string => (process.platform === 'win32' ? value.toLowerCase() : value)
    if (normalize(await realpath(root)) !== normalize(canonical)) return 0
    directories = await readdir(root)
  } catch {
    return 0
  }
  let removed = 0
  for (const name of directories) {
    if (!/^[a-f0-9]{24}$/u.test(name)) continue
    const directory = path.join(root, name)
    try {
      const info = await lstat(directory)
      if (!info.isDirectory() || info.isSymbolicLink()) continue
      const files = await readdir(directory)
      const owned = ['loader.mjs', 'companion.mjs', 'companion.patch.yml']
      if (
        !files.includes('loader.mjs') ||
        !files.includes('companion.patch.yml') ||
        files.some((file) => !owned.includes(file))
      )
        continue
      const stats = await Promise.all(files.map((file) => lstat(path.join(directory, file))))
      if (stats.some((file) => !file.isFile() || file.isSymbolicLink() || file.size > 20_971_520)) continue
      const loader = await readFile(path.join(directory, 'loader.mjs'), 'utf8')
      const patch = await readFile(path.join(directory, 'companion.patch.yml'), 'utf8')
      const declared =
        /^- insert:\r?\n {4}- id: vscode-editor-bridge(?:-managed)?\r?\n {6}name: ("[^\r\n]+")\r?\n?$/u.exec(
          patch,
        )?.[1]
      const declaredLoader: unknown = declared === undefined ? undefined : JSON.parse(declared)
      const normalize = (value: string): string =>
        process.platform === 'win32' ? path.resolve(value).toLowerCase() : path.resolve(value)
      if (
        !loader.includes("export const name = 'vscode-editor-bridge'") ||
        !loader.includes('loadCompanion(runtimeRequire)') ||
        typeof declaredLoader !== 'string' ||
        normalize(declaredLoader) !== normalize(path.join(directory, 'loader.mjs'))
      )
        continue
      for (const file of files) await unlink(path.join(directory, file))
      await rmdir(directory)
      removed += 1
    } catch {
      /* Locked or changed artifacts remain available for a later migration attempt. */
    }
  }
  try {
    await rmdir(root)
  } catch {
    /* Keep directories with unrecognized or locked entries. */
  }
  return removed
}
